import json

with open('results/rule_based_accuracy_v1_rerun.json') as f:
    v1 = json.load(f)
with open('results/rule_based_accuracy_v2_test.json') as f:
    v2 = json.load(f)

# Get per-task episode counts
v1_tasks = {}
v2_tasks = {}

if 'per_task' in v1:
    for k, v in v1['per_task'].items():
        v1_tasks[k] = v.get('n_episodes', 0)
if 'per_task' in v2:
    for k, v in v2['per_task'].items():
        v2_tasks[k] = v.get('n_episodes', 0)

all_tasks = sorted(set(list(v1_tasks.keys()) + list(v2_tasks.keys())))
print(f'v1 tasks: {len(v1_tasks)}, v2 tasks: {len(v2_tasks)}')
print(f'v1 total eps: {sum(v1_tasks.values())}, v2 total eps: {sum(v2_tasks.values())}')
print()
for t in all_tasks:
    c1 = v1_tasks.get(t, 0)
    c2 = v2_tasks.get(t, 0)
    if c1 != c2:
        print(f'DIFF: {t}: v1={c1}, v2={c2}')

# Check if keys differ
v1_only = set(v1_tasks.keys()) - set(v2_tasks.keys())
v2_only = set(v2_tasks.keys()) - set(v1_tasks.keys())
if v1_only:
    print(f'Tasks only in v1: {v1_only}')
if v2_only:
    print(f'Tasks only in v2: {v2_only}')
